// ============================================
// n8n CODE NODE
// Filter Supplier Entries Using Dynamic Input
// ============================================

// estimate entries
const entries =
  $('retrieve_estimate').first().json.entries || [];

// supplier task type master list
const supplierTaskTypes =
  $input.first().json["Task Type"] || [];

// ============================================
// BUILD ALLOWED LOOKUPS
// ============================================

const allowedCodes = new Set();
const allowedDescriptions = new Set();

for (const item of supplierTaskTypes) {

  const value =
    String(item || '').trim();

  if (!value) continue;

  const parts =
    value.split('|');

  const code =
    String(parts[0] || '')
      .trim()
      .toUpperCase();

  const description =
    String(parts[1] || '')
      .trim();

  if (code) {
    allowedCodes.add(code);
  }

  if (description) {
    allowedDescriptions.add(description);
  }
}

// ============================================
// UNIQUE TRACKER
// ============================================

const seen = new Set();

// ============================================
// FILTER ENTRIES
// ============================================

const supplierEntries =
  entries.filter(entry => {

    const taskCode =
      String(
        entry.taskTypeCode || ''
      )
      .trim()
      .toUpperCase();

    const description =
      String(
        entry.description || ''
      )
      .trim();

    const isSupplier = (

      allowedCodes.has(taskCode) ||

      allowedDescriptions.has(description)

    );

    if (!isSupplier) {
      return false;
    }

    const uniqueKey =
      `${taskCode}_${description}`;

    if (seen.has(uniqueKey)) {
      return false;
    }

    seen.add(uniqueKey);

    return true;
  });

// ============================================
// OUTPUT
// ============================================

return [
  {
    json: {
      supplier_entries_found:
        supplierEntries.length > 0,

      message:
        supplierEntries.length > 0
          ? 'Supplier entries found'
          : 'No suppliers found',

      supplier_entries:
        supplierEntries
    }
  }
];

// ============================================
// n8n CODE NODE
// Dynamic Supplier Lookup
// ============================================

// supplier entries from previous node
const supplierEntries =
  $input.first().json.supplier_entries || [];

// ============================================
// MASTER DATA
// ============================================

const taskTypes =
  $('Aggregate1').first().json["Task Type"] || [];

const favouriteSuppliers =
  $('Aggregate1').first().json["Favourite Supplier"] || [];

// ============================================
// BUILD DYNAMIC MAP
// ============================================

const supplierMap = {};

for (
  let i = 0;
  i < Math.min(
    taskTypes.length,
    favouriteSuppliers.length
  );
  i++
) {

  const taskTypeRow =
    String(taskTypes[i] || '').trim();

  const supplierRow =
    String(favouriteSuppliers[i] || '').trim();

  // ------------------------------------------
  // TASK TYPE
  // EXMO | Freelance Motion Designer (External)
  // ------------------------------------------

  const taskParts =
    taskTypeRow.split('|');

  const taskTypeCode =
    String(taskParts[0] || '')
      .trim()
      .toUpperCase();

  const taskTypeName =
    String(taskParts.slice(1).join('|') || '')
      .trim();

  // ------------------------------------------
  // SUPPLIER
  // BAZS | Bazaar Studios
  // ------------------------------------------

  const supplierParts =
    supplierRow.split('|');

  const supplierCode =
    String(supplierParts[0] || '')
      .trim()
      .toUpperCase();

  const supplierName =
    String(supplierParts.slice(1).join('|') || '')
      .trim();

  // map by description
  if (taskTypeName) {

    supplierMap[taskTypeName] = {

      task_type_code:
        taskTypeCode,

      supplier_code:
        supplierCode,

      supplier_name:
        supplierName

    };
  }
}

// ============================================
// PROCESS ENTRIES
// ============================================

const seen = new Set();

const results = [];

for (const entry of supplierEntries) {

  const taskTypeName =
    String(
      entry.description || ''
    ).trim();

  const supplier =
    supplierMap[taskTypeName];

  if (!supplier) {
    continue;
  }

  const uniqueKey =
    `${taskTypeName}_${supplier.supplier_code}`;

  if (seen.has(uniqueKey)) {
    continue;
  }

  seen.add(uniqueKey);

  results.push({

    found: true,

    task_type_name:
      taskTypeName,

    task_type_code:
      supplier.task_type_code,

    supplier_name:
      supplier.supplier_name,

    supplier_code:
      supplier.supplier_code

  });
}

// ============================================
// OUTPUT
// ============================================

if (results.length === 0) {

  return [
    {
      json: {
        found: false,
        message: 'No supplier matches found'
      }
    }
  ];
}

return results.map(item => ({
  json: item
}));

// ============================================
