// Output Supplier ID, Code, Name
// ============================================

const items = $input.all();

const results = [];

for (const item of items) {

  const supplier =
    item.json.data?.[0];

  if (!supplier) {
    continue;
  }

  results.push({

    supplier_id:
      supplier.id,

    office_id:
      supplier.officeId,

    supplier_code:
      supplier.code,

    supplier_name:
      supplier.name

  });
}

return results.map(item => ({
  json: item
}));

