// Prepare PO Entry Payload
// One PO -> One Matching Entry
// ============================================

// ============================================
// INPUTS
// ============================================

const createdPOs =
  $('PO Creation')
    .first()
    .json
    .created_PO_data || [];

const supplierEntries =
  $input.first()
    .json
    .supplier_entries || [];

const poNotes =
  $input.first()
    .json
    .PO_notes || [];

// supplier lookup node output
const supplierLookup =
  $('get_suppliers ID')
    .all();

// ============================================
// JOB ID
// ============================================

const JOB_ID =
  $('retrieve_estimate')
    .first()
    .json
    .jobId || null;

// ============================================
// HELPERS
// ============================================

function safeString(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  return String(value).trim();
}

// ============================================
// NOTES MAP
// ============================================

const notesMap = {};

for (const note of poNotes) {

  const key =
    safeString(note.task_type);

  notesMap[key] =
    safeString(note.po_note);
}

// ============================================
// BUILD SUPPLIER ID MAP
// supplierId -> supplierCode
// ============================================

const supplierIdMap = {};

for (const item of supplierLookup) {

  const supplier =
    item.json?.data?.[0];

  if (!supplier) {
    continue;
  }

  supplierIdMap[supplier.id] =
    supplier.code;
}

// ============================================
// TASK TYPE -> SUPPLIER CODE
// ============================================

const supplierMap = {

  'Freelance Designer (External)': 'FBIR',
  'Freelance Motion Designer (External)': 'BAZS',
  'Freelance Senior Designer (External)': 'FBIR',
  'Freelance Editor': 'RMKM',
  'HTML Developer': 'HERB',
  'Photography': 'PHOL',
  'Powerpoint Designer': 'GIOH',
  'Post Production': 'WHCH',
  'Producer': 'MEJU',
  'Research': 'LISB',
  'Retouching': 'ANCR',
  'Chief Strategy Officer': 'TRNA',
  'Proof Reader': 'PRCO'

};

// ============================================
// BUILD ENTRIES
// ============================================

const purchaseOrderEntries = [];

for (const po of createdPOs) {

  const poSupplierId =
    po.supplierId;

  const poSupplierCode =
    supplierIdMap[poSupplierId];

  if (!poSupplierCode) {
    continue;
  }

  // ==========================================
  // FIND MATCHING SUPPLIER ENTRY
  // ==========================================

  const matchedEntry =
    supplierEntries.find(entry => {

      const taskTypeName =
        safeString(entry.description);

      const supplierCode =
        supplierMap[taskTypeName];

      return (
        supplierCode ===
        poSupplierCode
      );
    });

  if (!matchedEntry) {
    continue;
  }

  const taskTypeName =
    safeString(
      matchedEntry.description
    );

  const note =
    notesMap[taskTypeName] ||
    taskTypeName;

  // ==========================================
  // CREATE SINGLE ENTRY
  // ==========================================

  purchaseOrderEntries.push({

    purchaseOrderId:
      po.id,

    billable: true,

    jobId:
      JOB_ID,

    taskTypeId:
      matchedEntry.taskTypeId,

    description: 
      taskTypeName,

    note:
      note,

    units: 1,

    rate:
      Number(
        matchedEntry.rate || 0
      )

  });
}

// ============================================
// OUTPUT
// ============================================

return [
  {
    json: {

      total_entries:
        purchaseOrderEntries.length,

      purchaseOrderEntries

    }
  }
];

